// Generates src/data/guides/index.ts so every guide JSON in the folder is bundled.
// Runs automatically before dev and build.
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(__dirname, "../src/data/guides");
const files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const ident = (f: string) => "g_" + f.replace(/\.json$/, "").replace(/[^a-z0-9]/gi, "_");
const out = [
  "// Generated by scripts/index-guides.ts. Do not edit.",
  ...files.map((f) => `import ${ident(f)} from "./${f}";`),
  "",
  `export const RAW_GUIDES: unknown[] = [${files.map(ident).join(", ")}];`,
  "",
].join("\n");
writeFileSync(join(dir, "index.ts"), out);
console.log(`Indexed ${files.length} guides`);
